class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        def isValid(comb: str) -> bool:
            openCount = 0
            for c in comb:
                if c == "(":
                    openCount += 1
                else:
                    openCount -= 1
                if openCount < 0:
                    return False
            return openCount == 0

        res = []
        def generateAll(comb: list) -> None:
            if len(comb) == 2 * n:
                if isValid(comb):
                    res.append("".join(comb))
                return
            comb.append("(")
            generateAll(comb)
            comb.pop()
            comb.append(")")
            generateAll(comb)
            comb.pop()

        generateAll([])
        return res
